from datetime import datetime, timedelta, time
import calendar
import re

def delivery_date(start, description):
    """
    Convert a delivery date description into an actual delivery datetime string
    based on meeting start.

    Accepts start as a datetime or an ISO-8601 string (e.g. "2013-11-21T15:30:00").
    Returns an ISO-8601 formatted string "YYYY-MM-DDTHH:MM:SS".
    """
    # Parse start if it's a string
    if isinstance(start, str):
        s = start
        # handle trailing Z for UTC
        if s.endswith('Z'):
            s = s[:-1] + '+00:00'
        start = datetime.fromisoformat(s)

    desc = description.strip().upper()
    tz = start.tzinfo

    def with_tz(dt):
        # Attach original tzinfo if present
        if tz is None:
            return dt
        return dt.replace(tzinfo=tz)

    def fmt(dt):
        # Return formatted string without timezone offset information
        # (tests expect "YYYY-MM-DDTHH:MM:SS")
        if dt.tzinfo is not None:
            dt = dt.replace(tzinfo=None)
        return dt.strftime("%Y-%m-%dT%H:%M:%S")

    # Fixed descriptions
    if desc == "NOW":
        result = start + timedelta(hours=2)
        return fmt(result)

    if desc == "ASAP":
        thirteen = time(13, 0, 0)
        if start.time() < thirteen:
            # Today at 17:00
            dt = datetime(start.year, start.month, start.day, 17, 0, 0)
            dt = with_tz(dt)
            return fmt(dt)
        else:
            # Tomorrow at 13:00
            tomorrow = start + timedelta(days=1)
            dt = datetime(tomorrow.year, tomorrow.month, tomorrow.day, 13, 0, 0)
            dt = with_tz(dt)
            return fmt(dt)

    if desc == "EOW":
        # Monday=0, Tuesday=1, Wednesday=2 -> Friday 17:00
        # Thursday=3, Friday=4 -> Sunday 20:00
        wd = start.weekday()
        if wd in (0, 1, 2):
            days_until_friday = 4 - wd
            target_day = start + timedelta(days=days_until_friday)
            dt = datetime(target_day.year, target_day.month, target_day.day, 17, 0, 0)
            dt = with_tz(dt)
            return fmt(dt)
        else:
            # Sunday at 20:00 (for Thursday, Friday, Saturday, Sunday -> next or same Sunday)
            days_until_sunday = (6 - wd)
            target_day = start + timedelta(days=days_until_sunday)
            dt = datetime(target_day.year, target_day.month, target_day.day, 20, 0, 0)
            dt = with_tz(dt)
            return fmt(dt)

    # Variable descriptions
    m_match = re.fullmatch(r'(\d{1,2})M', desc)
    if m_match:
        n = int(m_match.group(1))
        if not (1 <= n <= 12):
            raise ValueError("Month number out of range in description")
        # If meeting start before N-th month => schedule this year's N-th month
        # Otherwise (in or after N) => next year's N-th month
        if start.month < n:
            year = start.year
        else:
            year = start.year + 1
        month = n
        # find first workday of that month
        day = 1
        last_day = calendar.monthrange(year, month)[1]
        while day <= last_day:
            if datetime(year, month, day).weekday() < 5:
                dt = datetime(year, month, day, 8, 0, 0)
                dt = with_tz(dt)
                return fmt(dt)
            day += 1
        raise RuntimeError("No workday found in month (unexpected)")

    q_match = re.fullmatch(r'Q([1-4])', desc)
    if q_match:
        n = int(q_match.group(1))
        # Determine quarter of start
        start_quarter = ((start.month - 1) // 3) + 1
        # If meeting start is before or in N-th quarter => this year; else next year
        if start_quarter <= n:
            year = start.year
        else:
            year = start.year + 1
        month = n * 3  # last month of quarter
        last_day = calendar.monthrange(year, month)[1]
        day = last_day
        while day >= 1:
            if datetime(year, month, day).weekday() < 5:
                dt = datetime(year, month, day, 8, 0, 0)
                dt = with_tz(dt)
                return fmt(dt)
            day -= 1
        raise RuntimeError("No workday found in quarter (unexpected)")

    raise ValueError(f"Unknown delivery date description: {description}")
